527	  // Recibo do cliente (pagamento final / venda direta) — mesma ideia do ticket de setor,
528	  // mas com preço/subtotal/desconto/gorjeta/total/forma de pagamento, pra impressora
529	  // configurada em Config > "Impressora do recibo" (ver restaurante.service.ts).
530	  formatarReciboTexto(
531	    restauranteNome: string,
532	    comanda: {
533	      mesas?: { numero: number; nome: string | null } | null;
534	      mesa_id?: number | null;
535	      cliente_mesa_nome?: string | null;
536	    },
537	    itens: { product_name?: string; quantity: number; unit_price?: number }[],
538	    valores: {
539	      subtotal: number;
540	      desconto?: number;
541	      acrescimo?: number;
542	      gorjeta?: number;
543	      taxaCartao?: number;
544	      total: number;
545	      formaPagamento: string;
546	      trocoDado?: number;
547	    },
548	    pagamentos?: { valor: number; forma_pagamento: string; origem: string }[],
549	  ): string {
550	    const fmt = (v?: number) => (v ?? 0).toFixed(2).replace('.', ',');
551	    const PAGAMENTO_LABEL: Record<string, string> = { pix: 'PIX', credit_card: 'Cartao', debit_card: 'Debito', cash: 'Dinheiro' };
552	    const NEGRITO_ON = '\x1b\x45\x01';
553	    const NEGRITO_OFF = SalaoService.MARCADOR_NEGRITO_OFF;
554	
555	    const linhas: string[] = [];
556	    linhas.push('\x1b\x40');
557	    linhas.push(this.removerAcentos(restauranteNome ?? 'RESTAURANTE'));
558	    linhas.push('RECIBO DE PAGAMENTO');
559	    linhas.push(comanda.mesa_id ? this.removerAcentos(`Mesa ${comanda.mesas?.numero ?? comanda.mesa_id}`) : 'Venda balcao');
560	    if (comanda.cliente_mesa_nome) linhas.push(this.removerAcentos(comanda.cliente_mesa_nome));
561	    linhas.push(new Date().toLocaleString('pt-BR'));
562	    linhas.push('--------------------------------');
563	    for (const item of itens) {
564	      linhas.push(this.removerAcentos(`${item.quantity}x ${item.product_name ?? 'Produto'}`));
565	      linhas.push(`R$ ${fmt((item.quantity ?? 0) * (item.unit_price ?? 0))}`);
566	    }
