672	    const subtotal = (itens ?? []).reduce((acc: number, i: any) => acc + i.quantity * i.unit_price, 0);
673	    const totalFinal = subtotal - (comanda.desconto_valor ?? 0) + (comanda.acrescimo_valor ?? 0);
674	
675	    // Se já teve pagamento parcial (garçom ou caixa), só registra o que ainda falta —
676	    // o ledger de comanda_pagamentos fica completo pra conferência.
677	    const { saldo } = await this.salaoService.saldoDevedor(id);
678	    const gorjeta = gorjetaValor ?? 0;
