680	    const taxaCartaoValor = await this.calcularTaxaCartao(restaurantId, valorACobrarBase, formaPagamento);
681	    // Em dinheiro, o cliente entrega pro que falta da comanda + gorjeta juntos nesse momento.
682	    const valorACobrar = parseFloat((valorACobrarBase + taxaCartaoValor).toFixed(2));
683	    let troco: number | null = null;
684	    if (formaPagamento === 'cash' && valorRecebido !== undefined) {
685	      if (valorRecebido < valorACobrar) throw new BadRequestException('Valor recebido não pode ser menor que o valor a pagar');
686	      troco = parseFloat((valorRecebido - valorACobrar).toFixed(2));
687	    }
688	
689	    if (saldo > 0.01) {
690	      await this.salaoService.registrarPagamento(id, 'estabelecimento', saldo, formaPagamento, restaurantId, undefined, undefined, taxaCartaoValor);
691	    }
692	
693	    if (formaPagamento === 'cash') {
694	      const identificador = `Comanda #${comanda.numero_comanda ?? id}`;
695	      if (gorjeta > 0) await this.salaoService.registrarSaidaCaixa(restaurantId, `Gorjeta - ${identificador}`, gorjeta, 'gorjeta');
696	      if (troco && troco > 0) await this.salaoService.registrarSaidaCaixa(restaurantId, `Troco - ${identificador}`, troco, 'troco');
697	    }
698	
699	    let caixaId = comanda.caixa_id;
700	    if (!caixaId) {
701	      const { data: caixaAberto } = await this.supabase.client
702	        .from('caixas')
703	        .select('id')
704	        .eq('restaurant_id', restaurantId)
705	        .eq('status', 'aberto')
706	        .maybeSingle();
707	      caixaId = caixaAberto?.id ?? null;
708	    }
709	
710	    const { error } = await this.supabase.client
711	      .from('orders')
712	      .update({
713	        status: 'paga',
714	        payment_method: formaPagamento,
715	        total: parseFloat(totalFinal.toFixed(2)),
716	        gorjeta_valor: gorjetaValor ?? null,
717	        caixa_id: caixaId,
718	      })
