1	import React, { useState, useEffect } from 'react';
2	import { getRelatorioGarcom, getMinhaEmpresa } from '../../services/restauranteService';
3	import RelatorioNav from './RelatorioNav';
4	import FiltroPeriodo from './FiltroPeriodo';
5	import { fmt, buildRange, printIframe, reportBaseStyle, printFooterScript, defaultFiltroState } from '../../utils/relatorioPrint';
6	
7	const buildPrintHtml = (garcons, restauranteNome, label) => {
8	  const rows = garcons.map((g) => `<tr>
9	    <td>${g.nome}</td>
10	    <td class="right bold green">${fmt(g.total_vendido)}</td>
11	    <td class="right">${fmt(g.total_comissao)}</td>
12	    <td class="right">${fmt(g.total_gorjeta)}</td>
13	    <td class="right">${g.comandas_abertas}</td>
14	    <td class="right">${g.comandas_pendentes}</td>
15	  </tr>`).join('');
16	
17	  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Relatório Garçom</title>
18	<style>${reportBaseStyle}</style></head><body>
19	<h1>${restauranteNome ?? 'RESTAURANTE'}</h1>
20	<div class="sub">Relatório por Garçom — ${label}</div>
21	<table>
22	  <tr><th>Garçom</th><th class="right">Total Vendido</th><th class="right">Comissão</th><th class="right">Gorjeta</th><th class="right">Comandas Abertas</th><th class="right">Pendentes</th></tr>
23	  ${rows || '<tr><td colspan="6">Nenhum garçom com movimento no período.</td></tr>'}
24	</table>
25	<footer>Emitido em: ${new Date().toLocaleString('pt-BR')}</footer>
26	${printFooterScript}
27	</body></html>`;
28	};
29	
30	const RelatorioGarcom = () => {
31	  const [restauranteNome, setRestauranteNome] = useState('');
32	  const [filtro, setFiltro] = useState(defaultFiltroState());
33	  const [garcons, setGarcons] = useState(null);
34	  const [label, setLabel] = useState('');
35	  const [loading, setLoading] = useState(false);
36	  const [erro, setErro] = useState(null);
37	
38	  useEffect(() => {
39	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
40	  }, []);
41	
42	  const buscar = async () => {
43	    const range = buildRange(filtro.modo, filtro.dia, filtro.mes, filtro.ano, filtro.periodoIni, filtro.periodoFim);
44	    if (!range) return;
45	    setLoading(true); setErro(null);
46	    try {
47	      const d = await getRelatorioGarcom(range.de, range.ate);
48	      setGarcons(d.garcons ?? []);
49	      setLabel(range.label);
50	    } catch (e) { setErro(e.message); }
51	    finally { setLoading(false); }
52	  };
53	
54	  useEffect(() => { buscar(); }, []); // eslint-disable-line
55	
56	  const totalVendido = (garcons ?? []).reduce((s, g) => s + g.total_vendido, 0);
57	  const totalComissao = (garcons ?? []).reduce((s, g) => s + g.total_comissao, 0);
58	  const totalGorjeta = (garcons ?? []).reduce((s, g) => s + g.total_gorjeta, 0);
59	
60	  return (
61	    <div className="min-h-screen bg-[#FAFAFA]">
62	      <RelatorioNav titulo="Garçom" />
63	      <main className="p-6 max-w-5xl mx-auto space-y-4">
64	        <FiltroPeriodo
65	          filtro={filtro} setFiltro={setFiltro} onBuscar={buscar} loading={loading}
66	          podeImprimir={!!garcons} onImprimir={() => printIframe(buildPrintHtml(garcons, restauranteNome, label))}
67	        />
68	
69	        {erro && <p className="text-sm text-red-600 bg-red-50 px-3 py-2 rounded-xl">{erro}</p>}
70	
71	        {garcons && (
72	          <>
73	            <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
74	              <div className="bg-white border border-green-200 rounded-2xl p-4 text-center">
75	                <p className="text-[10px] font-black text-green-600 uppercase tracking-widest mb-1">Total Vendido</p>
76	                <p className="text-2xl font-black text-green-700">{fmt(totalVendido)}</p>
77	              </div>
78	              <div className="bg-white border border-[#E4E4E7] rounded-2xl p-4 text-center">
79	                <p className="text-[10px] font-black text-[#71717A] uppercase tracking-widest mb-1">Comissão Total</p>
80	                <p className="text-2xl font-black text-[#18181B]">{fmt(totalComissao)}</p>
81	              </div>
82	              <div className="bg-white border border-[#E4E4E7] rounded-2xl p-4 text-center">
83	                <p className="text-[10px] font-black text-[#71717A] uppercase tracking-widest mb-1">Gorjeta Total</p>
84	                <p className="text-2xl font-black text-[#18181B]">{fmt(totalGorjeta)}</p>
85	              </div>
86	            </div>
87	
88	            <div className="bg-white rounded-2xl border border-[#E4E4E7] overflow-hidden">
89	              {garcons.length === 0 ? (
90	                <p className="text-sm text-[#71717A] text-center py-10">Nenhum garçom cadastrado ou sem movimento no período.</p>
91	              ) : (
92	                <div className="overflow-x-auto">
93	                  <table className="w-full text-sm">
94	                    <thead>
95	                      <tr className="bg-[#FAFAFA] border-b border-[#F4F4F5] text-xs font-bold text-[#71717A] uppercase tracking-widest">
96	                        <th className="text-left px-5 py-3">Garçom</th>
97	                        <th className="text-right px-5 py-3">Total Vendido</th>
98	                        <th className="text-right px-5 py-3">Comissão</th>
99	                        <th className="text-right px-5 py-3">Gorjeta</th>
100	                        <th className="text-right px-5 py-3">Comandas Abertas</th>
101	                        <th className="text-right px-5 py-3">Pendentes</th>
102	                      </tr>
103	                    </thead>
104	                    <tbody className="divide-y divide-[#F4F4F5]">
105	                      {garcons.map((g) => (
106	                        <tr key={g.garcom_id} className="hover:bg-[#FAFAFA]">
107	                          <td className="px-5 py-3 font-semibold text-[#18181B]">{g.nome}</td>
108	                          <td className="px-5 py-3 text-right font-bold text-green-700">{fmt(g.total_vendido)}</td>
109	                          <td className="px-5 py-3 text-right">{fmt(g.total_comissao)}</td>
110	                          <td className="px-5 py-3 text-right">{fmt(g.total_gorjeta)}</td>
111	                          <td className="px-5 py-3 text-right">
112	                            {g.comandas_abertas > 0
113	                              ? <span className="px-2 py-0.5 rounded-full text-xs font-bold bg-blue-100 text-blue-800">{g.comandas_abertas}</span>
114	                              : <span className="text-[#A1A1AA]">0</span>}
115	                          </td>
116	                          <td className="px-5 py-3 text-right">
117	                            {g.comandas_pendentes > 0
118	                              ? <span className="px-2 py-0.5 rounded-full text-xs font-bold bg-amber-100 text-amber-800">{g.comandas_pendentes}</span>
119	                              : <span className="text-[#A1A1AA]">0</span>}
120	                          </td>
121	                        </tr>
122	                      ))}
123	                    </tbody>
124	                  </table>
125	                </div>
126	              )}
127	            </div>
128	          </>
129	        )}
